const growthTeacher=document.createElement('section');growthTeacher.className='teacher-card';growthTeacher.innerHTML='<h2>성장 여권 · 교사 도장</h2><p>하루 10분 이상 공부하고 마무리한 날을 셉니다. 수업일 기준은 아래 버튼으로 기록한 날짜만 세며, 과거 도장은 유지됩니다.</p><label>연속 출석 기준<select id="growthMode"><option value="calendar">매일 · 주말 포함</option><option value="school">교사가 지정한 수업일만</option></select></label><button id="saveGrowthMode">기준 저장</button><button id="markSchoolday">오늘을 수업일로 기록</button><p id="growthSchedule"></p><form id="awardNeighbor"><h3>고마운 이웃 도장 · 학생당 1회</h3><label>학생<select id="awardStudent"></select></label><label>관찰한 도움과 협력<input id="awardReason" minlength="2" maxlength="120" required placeholder="예: 친구의 작물 포장을 도와주었어요"></label><button type="submit">도장 찍어 주기</button></form><p id="growthTeacherStatus" role="status"></p>';document.querySelector('#teacherDashboard').append(growthTeacher);
let growthTeacherRoom='';const beforeGrowthTeacher=show;show=function(d,force=false){beforeGrowthTeacher(d,force);const awardSelect=document.querySelector('#awardStudent'),previousAward=growthTeacherRoom===d.room.id?awardSelect.value:'';awardSelect.innerHTML=d.players.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.accountName)}</option>`).join('');if(previousAward&&d.players.some(p=>p.id===previousAward))awardSelect.value=previousAward;if(growthTeacherRoom!==d.room.id){growthTeacherRoom=d.room.id;readGrowthTeacher()}};
async function readGrowthTeacher(){try{const d=await request('/api/growth');if(d.home!==growthTeacherRoom)return;document.querySelector('#growthMode').value=d.mode;document.querySelector('#growthSchedule').textContent='지정한 수업일: '+(d.schooldays.join(', ')||'없음')}catch(e){document.querySelector('#growthTeacherStatus').textContent=e.message}}
async function writeGrowthTeacher(path,body){try{await request(path,body);document.querySelector('#growthTeacherStatus').textContent='선택한 학급에 저장했어요.';await readGrowthTeacher()}catch(e){document.querySelector('#growthTeacherStatus').textContent=e.message}}
document.querySelector('#saveGrowthMode').onclick=()=>writeGrowthTeacher('/api/growth/policy',{mode:document.querySelector('#growthMode').value});document.querySelector('#markSchoolday').onclick=()=>writeGrowthTeacher('/api/growth/schoolday',{});document.querySelector('#awardNeighbor').onsubmit=e=>{e.preventDefault();writeGrowthTeacher('/api/growth/award',{actor:document.querySelector('#awardStudent').value,reason:document.querySelector('#awardReason').value})};
